SPECIFICATION:

I would like you to implement a module named TopModule with the following
interface. All input and output ports are one bit unless otherwise
specified.

 - input  clk
 - input  reset
 - input  in
 - output out

Implement the following Moore state machine with two states, one input,
and one output. The reset state is B and reset is active-high
synchronous.

  B (out=1) --in=0--> A
  B (out=1) --in=1--> B
  A (out=0) --in=0--> B
  A (out=0) --in=1--> A



CANDIDATE RTL TO ATTACK:
```verilog
module TopModule (
    input  wire clk,
    input  wire reset,
    input  wire in,
    output wire out
);

    // State encoding: State B = 1'b1, State A = 1'b0
    // Reset state is B, so default/reset value is 1'b1.
    reg current_state, next_state;

    parameter STATE_B = 1'b1;
    parameter STATE_A = 1'b0;

    // Sequential logic: synchronous active-high reset
    always @(posedge clk) begin
        if (reset) begin
            current_state <= STATE_B;
        end else begin
            current_state <= next_state;
        end
    end

    // Combinational logic for next-state determination
    always @(*) begin
        case (current_state)
            STATE_B: begin
                if (in == 1'b0)
                    next_state = STATE_A;
                else
                    next_state = STATE_B;
            end
            STATE_A: begin
                if (in == 1'b0)
                    next_state = STATE_B;
                else
                    next_state = STATE_A;
            end
            default: begin
                next_state = STATE_B;
            end
        endcase
    end

    // Moore machine output depends only on the current state
    // B (out = 1), A (out = 0)
    assign out = (current_state == STATE_B) ? 1'b1 : 1'b0;

endmodule
```

